(function(){
'use strict';
const esc=value=>String(value||'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function typeOf(name){const value=name.toLowerCase();if(/national park|nature reserve|game reserve|sanctuary|conservancy|biosphere/.test(value))return'Protected area';if(/lake|delta|wetland|river|falls|coast|marine|archipelago|island|beach|ocean|nile/.test(value))return'Water & coast';if(/mount|mountain|massif|highland|plateau|escarpment|peak|pass/.test(value))return'Mountains';if(/desert|pan|dune|sahara|ténéré|kalahari|namib/.test(value))return'Desert & pans';if(/valley|forest|rainforest|woodland/.test(value))return'Landscape';return'Place';}
window.countryDestinationHtml=(country,atlasRow)=>{const destinations=String(atlasRow?.[2]||'').split('·').map(item=>item.trim()).filter(Boolean);if(!destinations.length)return'';return `<section class="entry-section destination-directory" data-destination-country="${esc(country)}"><div class="entry-kicker">PLACE DIRECTORY</div><div class="destination-directory-head"><div><h3>Explore ${esc(country)}</h3><p>${destinations.length} Pocketbook starting points, each linked to live geographic search.</p></div><button type="button" data-find-country="${esc(country)}">Search all places</button></div><div class="country-destination-grid">${destinations.map(name=>`<button type="button" data-find-destination="${esc(name)}, ${esc(country)}"><span>${esc(typeOf(name))}</span><strong>${esc(name)}</strong><small>Show on map →</small></button>`).join('')}</div></section>`};
window.mountCountryDestinations=()=>document.querySelectorAll('[data-find-destination],[data-find-country]').forEach(button=>button.addEventListener('click',()=>{const query=button.dataset.findDestination||button.dataset.findCountry;document.querySelector('.country-close')?.click();window.openPocketbookView?.('map');setTimeout(()=>{const input=document.getElementById('mapSearch');if(!input)return;input.value=query;input.dispatchEvent(new Event('input',{bubbles:true}));document.getElementById('searchAllAfrica')?.click();document.querySelector('.map-sidebar')?.scrollIntoView({behavior:'smooth',block:'start'})},120)}));
})();
